L["SARKARETH: Bomben soaken, Leere-Flächen raus aus dem Raid!"] = "萨卡雷斯：分摊炸弹，虚空地面跑出团队！"
L["Tankwechsel nach Ansage. Raid-CDs in Phase 3."] = "按指挥换坦。阶段3开团队减伤。"
L["Amirdrassil, die Hoffnung des Traums"] = "阿梅达希尔，梦境之愿"
L["Knorrwurz + gequälte Wurzeln"] = "瘤根 + 痛苦根须"
