L["SMOLDERON: Brandmal gemeinsam soaken, Flächen raus!"] = "斯莫德隆：一起分摊烙印，地面跑出去！"
L["Zwischenphase: Kugeln sammeln, Raid-CDs."] = "转阶段：收集火球，团队减伤。"
L["Tindral Weisenschnelle, Seher der Flamme"] = "丁达尔·迅贤，烈焰先知"
